before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
class Session {
    int minutes;
public:
    explicit Session(int n) : minutes{n} {}
    int duration() const { return minutes; }
};
int main() {
    Session s{12};
    std::cout << s.duration() << '\n';
}

```

